    'bulk_upload_logo_hosting_title' => 'Where can I host the logo images?',
    'bulk_upload_logo_hosting_intro' => 'The "logo_url" column accepts any publicly reachable image URL — the importer downloads the file server-side. If you do not already have a place to host the images, these cloud storage providers all offer free or low-cost options that give you a public URL per file:',
    'bulk_upload_logo_hosting_cloud_storage' => 'Cloud storage with public URLs',
    'bulk_upload_logo_cloudflare_r2_desc' => 'S3-compatible object storage. Generous free tier (10 GB) with zero egress fees — the cheapest option once you scale.',
    'bulk_upload_logo_aws_s3_desc' => 'Industry standard. 5 GB free for the first 12 months, then pay-as-you-go. Pair with CloudFront if you need CDN-level latency.',
    'bulk_upload_logo_backblaze_desc' => 'Low-cost object storage. 10 GB free indefinitely; very cheap beyond that.',
    'bulk_upload_logo_github_desc' => 'Simplest option — commit images to a public repo and use raw.githubusercontent.com URLs. Free, indefinite, no setup.',
    'bulk_upload_logo_hosting_note' => 'Tip: prefer HTTPS URLs and keep each image under :mb MB (configurable via BULK_UPLOAD_LOGO_MAX_BYTES). Oversized files are soft-failed per row.',
    'bulk_upload_translation_instructions_title' => 'How to upload multi-language translations',
    'bulk_upload_translation_instructions_intro' => 'You can import and manage translations for active languages in two ways:',
    'bulk_upload_translation_mode_standard_title' => '1. Standard Create & Update Mode (All Languages in One CSV)',
    'bulk_upload_translation_mode_standard_desc' => 'The standard template contains columns for canonical English text (e.g. title, description) and optional columns for other active languages (e.g. title_es, description_es, title_ar). English is required when creating new items; non-English columns are optional and will fallback to English if left blank.',
    'bulk_upload_translation_mode_dedicated_title' => '2. Dedicated Translation Mode (Per-Language Workflow)',
    'bulk_upload_translation_step1' => 'Upload your CSV and click "Load preview", then select "Translation Mode" under the Upload Mode dropdown in Step 2.',
    'bulk_upload_translation_step2' => 'Click "Download Translation Template" and select your target language (e.g. Spanish, Arabic). The exported CSV includes the immutable "uuid", canonical English reference text, and target language columns.',
    'bulk_upload_translation_step3' => 'Fill in the translations in the target language columns. Items are matched strictly by "uuid" — do NOT alter or delete the uuid column.',
    'bulk_upload_translation_step4' => 'Leave cells blank to keep existing translations untouched.',
    'bulk_upload_translation_step5' => 'Enter "__DELETE__" in a translation cell to remove an existing non-English translation and revert it to the English fallback.',
    'bulk_upload_translation_step6' => 'Single-language translation uploads are isolated and will never modify other languages or canonical English data.',
